// CalculateRequest defines model for CalculateRequest.
type CalculateRequest struct {
	// Ayanamsha Ayanamsha
	Ayanamsha *string `json:"ayanamsha,omitempty"`

	// City City name (optional)
	City *string `json:"city,omitempty"`

	// D4Profile D4 only: auto uses AstroSage Lahiri/Raman with mean nodes in 1600–2399; otherwise Swiss. Explicit AstroSage profiles require mean nodes. Generic kp stays Swiss; select astrosage_kp_new, astrosage_kp_old or astrosage_kp_khullar explicitly. Other divisions and the main chart keep their existing calculation basis.
	D4Profile *CalculateRequestD4Profile `json:"d4_profile,omitempty"`

	// DashaLevels Dasha depth (0=off, 1=Maha, 2=+Antar, 3=+Pratyantar).
	DashaLevels *int `json:"dasha_levels,omitempty"`

	// DashaMode Vimshottari dasha calculation profile. Use astrosage only when exact AstroSage compatibility is required.
	DashaMode *CalculateRequestDashaMode `json:"dasha_mode,omitempty"`

	// Day Day of birth (1-31)
	Day int `json:"day"`

	// Hour Hour of birth (0-23)
	Hour int `json:"hour"`

	// HouseSystem House system
	HouseSystem *string `json:"house_system,omitempty"`

	// IncludeAshtakavarga Include V2 Ashtakavarga strength.
	IncludeAshtakavarga *bool `json:"include_ashtakavarga,omitempty"`

	// IncludeAvastha Include Baladi Avastha planet age state in chart.planets[].
	IncludeAvastha *bool `json:"include_avastha,omitempty"`

	// IncludeBhavaChalit Include Bhava Chalit as an adjacent top-level BC chart component.
	IncludeBhavaChalit *bool `json:"include_bhava_chalit,omitempty"`

	// IncludePanchang Include V2 Panchang.
	IncludePanchang *bool `json:"include_panchang,omitempty"`

	// IncludeShadbala Include V2 Shadbala strength.
	IncludeShadbala *bool `json:"include_shadbala,omitempty"`

	// IncludeYogas Include V2 yoga detection.
	IncludeYogas *bool `json:"include_yogas,omitempty"`

	// Lat Latitude
	Lat *float64 `json:"lat,omitempty"`

	// Lng Longitude
	Lng *float64 `json:"lng,omitempty"`

	// Minute Minute of birth (0-59)
	Minute int `json:"minute"`

	// Month Month of birth (1-12)
	Month int `json:"month"`

	// NodeType Node type (mean/true)
	NodeType *string `json:"node_type,omitempty"`

	// ReferenceDate Reference date for active dasha lookup and Sade Sati. Defaults to today in timezone_used.
	ReferenceDate *openapi_types.Date `json:"reference_date,omitempty"`

	// Second Second of birth (0-59)
	Second *int `json:"second,omitempty"`

	// TzStr Timezone: AUTO, LMT, or standard (e.g. Europe/Berlin)
	TzStr *string `json:"tz_str,omitempty"`

	// Vargas Divisional charts to include. Supports D1, D2, D3, D4, D5, D7, D9, D10, D12, D16, D20, D24, D27, D30, D40, D45, and D60.
	Vargas *[]int `json:"vargas,omitempty"`

	// Year Astronomical year of birth (0-2399; 0 = 1 BCE)
	Year int `json:"year"`
}

// CalculateRequestD4Profile D4 only: auto uses AstroSage Lahiri/Raman with mean nodes in 1600–2399; otherwise Swiss. Explicit AstroSage profiles require mean nodes. Generic kp stays Swiss; select astrosage_kp_new, astrosage_kp_old or astrosage_kp_khullar explicitly. Other divisions and the main chart keep their existing calculation basis.
